<script setup lang="ts">import{computed}from 'vue';import type{Correction}from '../types/domain';import{fmt,ratio}from '../utils/format';const p=defineProps<{correction:Correction}>();
const labels:Record<string,string>={higher:'A更高',lower:'A更低',equal:'无方向',undefined:'未定义'};
function shifts(c:Correction){return c.strata.map(s=>`${s.code} ${s.k>0?'+':''}${s.k}`).join(' / ')}</script>
<template><div class="correction-card"><p class="eyebrow">修正 #{{correction.ordinal}} · S={{correction.observed_sum_a}}</p><p class="correction-shift">{{shifts(correction)}}</p><dl><div><dt>共同OR</dt><dd>{{ratio(correction.adjusted_or)}} <small>{{labels[correction.direction]}}</small></dd></div><div><dt>CMH</dt><dd>{{fmt(correction.cmh,6)}}</dd></div><div><dt>精确双侧p</dt><dd>{{correction.exact_p.display}}<small v-if="correction.exact_p.underflow">（double下溢，见log）</small></dd></div><div><dt>p log</dt><dd>{{fmt(correction.exact_p.log,8)}}</dd></div><div><dt>p ≤ α</dt><dd>{{correction.below_alpha?'是':'否'}}</dd></div></dl><details><summary>修正后的四格</summary><div class="table-wrap"><table><thead><tr><th>层</th><th>k</th><th>a</th><th>b</th><th>c</th><th>d</th></tr></thead><tbody><tr v-for="s in correction.strata" :key="s.code"><td>{{s.code}}</td><td>{{s.k>0?'+':''}}{{s.k}}</td><td>{{s.a}}</td><td>{{s.b}}</td><td>{{s.c}}</td><td>{{s.d}}</td></tr></tbody></table></div></details></div></template>
